-- validator._drop_marks: NFD, combining accents except breve and diaeresis removed, NFC
CREATE OR REPLACE FUNCTION ac.drop_marks(s text) RETURNS text IMMUTABLE LANGUAGE sql AS $$
  SELECT normalize(regexp_replace(normalize(s, NFD), '[\u0300-\u0305\u0307\u0309-\u036F\u1AB0-\u1AFF\u1DC0-\u1DFF\u20D0-\u20FF\uFE20-\uFE2F]', '', 'g'), NFC) $$;
